	var delta := Vector3(target.x - _player.global_position.x,
	                     0.0,
	                     target.z - _player.global_position.z)
	var dist := delta.length()
	if dist < close_dist:
		for a in [&"move_forward", &"move_back", &"move_left", &"move_right"]:
